import React, { useState } from 'react';
import CountDownBox from 'react-countdown';

import { CountUp } from './CountUp';

import './index.scss';

const SAVE_THE_DATE = '2024-05-13 11:00:00';

export function CountDown() {
  const [isCompleted] = useState(Date.now() > new Date(SAVE_THE_DATE).getTime());
  const targetTime = new Date(SAVE_THE_DATE);

  return (
    <div className="countdown-container">
      <div className="container">
        <div className="row">
          <div className="col-12 text-center">
            <h2 className="title">{isCompleted ? 'Đếm xuôi' : 'Đếm Ngược'}</h2>
            <div className="countdown-box">
              <CountDownBox
                date={targetTime}
                renderer={({ days, hours, minutes, seconds, completed }) => {
                  if (completed) {
                    // Render a completed state
                    return <CountUp target={SAVE_THE_DATE} />;
                  } else {
                    return (
                      <div className="row justify-content-center">
                        <div className="col-auto">
                          <div className="number-box">{days}</div>
                          <div className="box-label">Ngày</div>
                        </div>
                        <div className="col-auto">
                          <div className="number-box">{hours}</div>
                          <div className="box-label">Giờ</div>
                        </div>
                        <div className="col-auto">
                          <div className="number-box">{minutes.toString().padStart(2, '0')}</div>
                          <div className="box-label">Phút</div>
                        </div>
                        <div className="col-auto">
                          <div className="number-box">{seconds.toString().padStart(2, '0')}</div>
                          <div className="box-label">Giây</div>
                        </div>
                      </div>
                    );
                  }
                }}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
