import React, { useMemo } from 'react';
import { calcDiffDates } from '../../../utils';

import './index.scss';

export const CountUp = ({ target }: any) => {
  const diff = useMemo(() => {
    let now = new Date();
    now = new Date(now.setHours(0, 0, 0, 0));
    const baseDate = new Date(target);
    return calcDiffDates(now, baseDate, 'vi');
  }, [target]);

  return (
    <div className="row justify-content-center">
      {diff.years > 0 && (
        <div className="col-auto">
          <div className="number-box">{diff.years}</div>
          <div className="box-label">Năm</div>
        </div>
      )}
      {diff.months > 0 && (
        <div className="col-auto">
          <div className="number-box">{diff.months}</div>
          <div className="box-label">Tháng</div>
        </div>
      )}
      {diff.days > 0 && (
        <div className="col-auto">
          <div className="number-box">{diff.days}</div>
          <div className="box-label">Ngày</div>
        </div>
      )}
    </div>
  )
}